import http from 'http';

const options = {
  hostname: 'colormind.io',
  port: 80,
  path: '/list/',
  method: 'GET'
};

const req = http.request(options, (res) => {
  let data = '';
  res.on('data', (chunk) => data += chunk);
  res.on('end', () => {
    try {
      const models = JSON.parse(data);
      console.log(JSON.stringify(models, null, 2));
    } catch (e) {
      console.log(data);
    }
  });
});

