      "keystrokes": "cat > scripts/generate_palette.mjs << 'EOF'
import http from 'http';

const args = process.argv.slice(2);
let model = 'default';
let input = ['N', 'N', 'N', 'N', 'N'];
let pretty = false;

for (let i = 0; i < args.length; i++) {
  if (args[i] === '--model' && args[i + 1]) {
    model = args[++i];
  } else if (args[i] === '--input') {
    input = [];
    while (i + 1 < args.length && !args[i + 1].startsWith('--')) {
      input.push(args[++i]);
    }
  } else if (args[i] === '--pretty') {
    pretty = true;
  }
}

const locked = input.map(slot => {
  if (slot === 'N') return null;
  const [r, g, b] = slot.split(',').map(Number);
  return [r, g, b];
});

const payload = {
  model,
  locked
};

const postData = JSON.stringify(payload);
const options = {
  hostname: 'colormind.io',
  port: 80,
  path: '/api/',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(postData)
  }
};

const req = http.request(options, (res) => {
  let data = '';
  res.on('data', (chunk) => data += chunk);
  res.on('end', () => {
    try {
      const result = JSON.parse(data);
      console.log(JSON.stringify(result, null, 2));

      if (pretty && result.palette) {
        console.log('\n--- Pretty Output ---');
        console.log(`Model: ${result.model || model}`);
        result.palette.forEach((color, i) => {
          const hex = `#${color.map(x => x.toString(16).padStart(2, '0')).join('')}`;
          console.log(`Color ${i + 1}: RGB(${color[0]}, ${color[1]}, ${color[2]}) - ${hex}`);
        });
      }
    } catch (e) {
      console.log(data);
    }
  });
});

req.on('error', (e) => {
  console.error('Error:', e.message);
  process.exit(1);
});

req.write(postData);
req.end();
EOF
",
      "duration": 0.1
    }
  ]
}

